"""Shipped map checks move to staging; altered generated bytes never qualify."""
from pathlib import Path
import shutil
import tempfile
import unittest

from tools import build

PROJECT = Path(__file__).resolve().parents[2]


class ShippedMapQualificationTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.stage = Path(self.temp.name)
        self.source = self.stage / 'Source'
        shutil.copytree(PROJECT / 'Source', self.source)

    def test_validated_generated_maps_receive_only_the_staged_flag(self):
        record = build.qualify_shipped_maps(self.source, self.stage)
        self.assertGreater(record['maps'], 0)
        self.assertIn('local mapsQualified <const> = true',
                      (self.source / 'game/shippedDataPolicy.lua').read_text())
        self.assertIn('local mapsQualified <const> = false',
                      (PROJECT / 'Source/game/shippedDataPolicy.lua').read_text())

    def test_changed_compact_cache_is_rejected_before_flag_publication(self):
        path = self.source / 'data/sourceMapCache/compact.json'
        path.write_bytes(path.read_bytes() + b' ')
        with self.assertRaisesRegex(ValueError, 'drift'):
            build.qualify_shipped_maps(self.source, self.stage)
        self.assertIn('local mapsQualified <const> = false',
                      (self.source / 'game/shippedDataPolicy.lua').read_text())

    def test_changed_binary_cells_are_rejected_before_flag_publication(self):
        path = next((self.source / 'data/sourceMapCells').glob('*.bin'))
        raw = bytearray(path.read_bytes())
        raw[-1] ^= 1
        path.write_bytes(raw)
        with self.assertRaisesRegex(ValueError, 'drift'):
            build.qualify_shipped_maps(self.source, self.stage)

    def test_changed_content_chunk_is_rejected_before_content_flag_publication(self):
        path = next((self.source / 'data/contentCache/chunks').glob('*.json'))
        path.write_bytes(path.read_bytes() + b' ')
        with self.assertRaisesRegex(ValueError, 'content cache drift'):
            build.qualify_shipped_content(PROJECT, self.source, self.stage)
        self.assertIn('local immutableContentQualified <const> = false',
                      (self.source / 'game/shippedDataPolicy.lua').read_text())

    def test_project_without_content_pins_keeps_the_deep_path(self):
        result = build.qualify_shipped_content(self.stage / 'minimal-project', self.source, self.stage)
        self.assertIsNone(result)
        self.assertIn('local immutableContentQualified <const> = false',
                      (self.source / 'game/shippedDataPolicy.lua').read_text())
